--
-- Name: COLUMN invoices.charge_attempt_seq; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.charge_attempt_seq IS 'Seeds the Stripe charge idempotency key (velox_inv_<id>_<seq>). Bumped ONLY by writes that record a charge attempt outcome — i.e. every UPDATE that stamps stripe_payment_intent_id. Never bumped by the auto-charge lease, and never by unrelated writers.';


--
-- Name: COLUMN invoices.provider_payment_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.provider_payment_status IS 'Verbatim Stripe PaymentIntent status at the last reconciler poll. An observation, not a money fact — payment_status remains authoritative.';


--
-- Name: COLUMN invoices.provider_synced_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.provider_synced_at IS 'When the reconciler last observed provider_payment_status. Orders the in-flight sweep so a never-resolving row cannot head the queue forever.';


--
-- Name: COLUMN invoices.bill_to_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.bill_to_snapshot IS 'Buyer details the invoice was issued with (domain.DocumentBillTo). Written when the invoice leaves draft; NULL on drafts and on invoices issued before migration 0177, which render live.';


--
-- Name: COLUMN invoices.supplier_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.supplier_snapshot IS 'Seller details the invoice was issued with (domain.DocumentSupplier). Written when the invoice leaves draft; NULL on drafts and on invoices issued before migration 0177, which render live.';


--
-- Name: leader_leases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.leader_leases (
    role text NOT NULL,
    holder_token bigint NOT NULL,
    holder_id text,
    acquired_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    expires_at timestamp with time zone,
    last_tick_ended_at timestamp with time zone,
    last_tick_holder text,
    paused_at timestamp with time zone,
    paused_by text,
    pause_reason text,
    not_before timestamp with time zone,
    CONSTRAINT leader_leases_held_shape CHECK ((((holder_id IS NULL) = (acquired_at IS NULL)) AND ((holder_id IS NULL) = (heartbeat_at IS NULL)) AND ((holder_id IS NULL) = (expires_at IS NULL)))),
    CONSTRAINT leader_leases_holder_id_check CHECK (((holder_id IS NULL) OR ((length(holder_id) >= 1) AND (length(holder_id) <= 200)))),
    CONSTRAINT leader_leases_holder_token_check CHECK ((holder_token > 0)),
    CONSTRAINT leader_leases_lease_after_acquire CHECK (((holder_id IS NULL) OR (expires_at > acquired_at))),
    CONSTRAINT leader_leases_pause_shape CHECK (((paused_at IS NULL) = (paused_by IS NULL))),
    CONSTRAINT leader_leases_paused_is_unheld CHECK (((paused_at IS NULL) OR (holder_id IS NULL))),
    CONSTRAINT leader_leases_role_check CHECK ((role = ANY (ARRAY['billing'::text, 'dunning'::text, 'webhook_outbox'::text, 'email_outbox'::text, 'webhook_delivery'::text])))
);


--
-- Name: COLUMN leader_leases.not_before; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leader_leases.not_before IS 'Acquire refuses until this instant (set after a lost tick, cleared by a completed one). Cadence only — never a completion.';


--
-- Name: leader_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.leader_status AS
 SELECT role,
    holder_id,
    holder_token,
    ((expires_at > now()) IS TRUE) AS held,
    acquired_at,
    heartbeat_at,
    expires_at,
    round(EXTRACT(epoch FROM (expires_at - now())), 1) AS expires_in_s,
    last_tick_holder,
    last_tick_ended_at,
    round(EXTRACT(epoch FROM (now() - last_tick_ended_at)), 1) AS last_tick_age_s,
    paused_at,
    paused_by,
    pause_reason,
    not_before,
    round(EXTRACT(epoch FROM (not_before - now())), 1) AS not_before_in_s
   FROM public.leader_leases;


