CREATE TABLE public.subscriptions (
    id text DEFAULT ('vlx_sub_'::text || encode(public.gen_random_bytes(12), 'hex'::text)) NOT NULL,
    tenant_id text NOT NULL,
    code text NOT NULL,
    display_name text NOT NULL,
    customer_id text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    billing_time text DEFAULT 'calendar'::text NOT NULL,
    trial_start_at timestamp with time zone,
    trial_end_at timestamp with time zone,
    started_at timestamp with time zone,
    activated_at timestamp with time zone,
    canceled_at timestamp with time zone,
    current_billing_period_start timestamp with time zone,
    current_billing_period_end timestamp with time zone,
    next_billing_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    usage_cap_units bigint,
    overage_action text DEFAULT 'charge'::text NOT NULL,
    livemode boolean DEFAULT true NOT NULL,
    test_clock_id text,
    cancel_at_period_end boolean DEFAULT false NOT NULL,
    cancel_at timestamp with time zone,
    pause_collection_behavior text,
    pause_collection_resumes_at timestamp with time zone,
    billing_threshold_amount_gte bigint,
    billing_threshold_reset_cycle boolean DEFAULT true NOT NULL,
    billing_anchor_day smallint DEFAULT 0 NOT NULL,
    billing_failed_for timestamp with time zone,
    billing_failure_count integer DEFAULT 0 NOT NULL,
    billing_failed_at timestamp with time zone,
    billing_next_attempt_at timestamp with time zone,
    billing_last_error text,
    CONSTRAINT subscriptions_billing_threshold_amount_gte_check CHECK (((billing_threshold_amount_gte IS NULL) OR (billing_threshold_amount_gte > 0))),
    CONSTRAINT subscriptions_billing_time_check CHECK ((billing_time = ANY (ARRAY['calendar'::text, 'anniversary'::text]))),
    CONSTRAINT subscriptions_pause_collection_behavior_check CHECK (((pause_collection_behavior IS NULL) OR (pause_collection_behavior = 'keep_as_draft'::text))),
    CONSTRAINT subscriptions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'trialing'::text, 'active'::text, 'canceled'::text, 'archived'::text]))),
    CONSTRAINT subscriptions_test_clock_requires_testmode CHECK (((test_clock_id IS NULL) OR (livemode = false)))
);

ALTER TABLE ONLY public.subscriptions FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN subscriptions.billing_failed_for; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.billing_failed_for IS 'The due instant the billing_* failure record is about. The record is live ONLY while this equals LEAST(next_billing_at, CASE WHEN status = ''active'' THEN cancel_at END) on a wall-clock (test_clock_id IS NULL) active or trialing row; otherwise the five billing_* columns are stale leftovers. Read them through domain.SubscriptionBillingFailingSQL, never bare.';


--
-- Name: COLUMN subscriptions.billing_next_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.billing_next_attempt_at IS 'Earliest next billing attempt for a live failure record (application clock). NULL on a live record means parked: nothing retries until POST /v1/subscriptions/{id}/retry-billing.';


